steps.script:
$o=@{state='pending'}
try{
 $p=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{[string]$_.CommandLine -match 'C:\\TTiTTulares\\Ejecutar[.]js' -and [string]$_.CommandLine -match ' --enviar'})
 if($p.Count){$o.state='runner_active'}
 else{
  $f=Join-Path $env:TEMP 'Reparar-TT-Editorial-20261111-inspect.ps1'
  Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/fabricelop/europapress-rss/9e6ead40c7e4dc5ab4391009c768230d4be70b67/windows/Reparar-TT-Editorial-20261111.ps1' -OutFile $f -TimeoutSec 30 -ErrorAction Stop
  & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $f -NoDispatch | Out-Null
  if($LASTEXITCODE -ne 0){throw 'INSTALL_FAILED'}
  $z=@(& node.exe 'C:\TTiTTulares\TT-Editorial-Guard.js' titulares --inspect-failed 2>&1)
  $line=[string]($z|Where-Object{$_ -match 'SAFE_COMPOSITOR_STATE'}|Select-Object -Last 1)
  if(-not $line){throw 'INSPECT_FAILED'}
  $j=$line.Substring($line.IndexOf('SAFE_COMPOSITOR_STATE')+22)|ConvertFrom-Json
  $o.state='inspected';$o.draft_length=[int]$j.editorLength;$o.placeholder_match=[bool]$j.placeholderMatch;$o.editor_tag=[string]$j.editorTag;$o.users=[int]$j.users;$o.assistants=[int]$j.assistants
 }
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
